package com.aoo.bcg.common.repair;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ImmutableRepairAuditTest{@Test void recordsVersionApprovalParametersAndResultOnce(){class Store implements ImmutableRepairAudit.AppendOnlyStore{ImmutableRepairAudit.Record value;public boolean exists(String id){return value!=null;}public void append(ImmutableRepairAudit.Record r){value=r;}}var store=new Store();String hash="a".repeat(64);var record=new ImmutableRepairAudit.Record("op","repair.sql",hash,"approval-1","operator",Map.of("limit","10"),hash,hash,"SUCCEEDED",Instant.EPOCH,Instant.EPOCH.plusSeconds(1));new ImmutableRepairAudit().append(store,record);assertEquals("approval-1",store.value.approvalId());assertThrows(IllegalStateException.class,()->new ImmutableRepairAudit().append(store,record));assertThrows(UnsupportedOperationException.class,()->record.parameters().put("x","y"));}}
